def finalText(ops):
    text = []
    done = []      # (kind, letter): kind 1 = typed, 2 = deleted
    undone = []
    for kind, value in ops:
        if kind == 1:
            ch = chr(96 + value)
            text.append(ch)
            done.append((1, ch))
            undone.clear()
        elif kind == 2:
            if text:
                done.append((2, text.pop()))
                undone.clear()
        elif kind == 3:
            if done:
                k, ch = done.pop()
                if k == 1:
                    text.pop()
                else:
                    text.append(ch)
                undone.append((k, ch))
        else:
            if undone:
                k, ch = undone.pop()
                if k == 1:
                    text.append(ch)
                else:
                    text.pop()
                done.append((k, ch))
    return "".join(text)
